uint16_t CRC16(uint16_t *buff, uint16_t size)
{
    uint16_t val = 0xFFFF;
    for(uint16_t i=0;i<size;i++)
    {
        val ^= buff[i];
        val = CRC16_Table[val];
    }
    return val;
}